
"""Hardware Health Monitoring API for Microsoft SCHIE Lab.

Uses simulated hardware telemetry, not physical devices.
"""

import json
import os
from collections import defaultdict
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from .remediation import simulate_remediation


# Location of the telemetry file generated by the C++ collector
DATA = Path(os.environ.get("TELEMETRY_FILE", "telemetry.jsonl"))


def analyze(lines):
    """Analyze telemetry and return the latest health of each device."""

    latest = {}
    counts = defaultdict(int)

    for line in lines:
        if not line.strip():
            continue

        record = json.loads(line)
        device = record["device_id"]

        counts[device] += 1

        if (
            device not in latest
            or record["sequence"] >= latest[device]["sequence"]
        ):
            latest[device] = record

    devices = []

    for device, record in sorted(latest.items()):
        unhealthy = (
            record["temp_c"] >= 80
            or record["power_w"] >= 240
        )

        devices.append({
            "device_id": device,
            "health": "degraded" if unhealthy else "healthy",
            "recommended_action": (
                "inspect_and_cool" if unhealthy else "none"
            ),
            "last_temp_c": record["temp_c"],
            "last_power_w": record["power_w"],
            "readings": counts[device],
        })

    return {
        "devices": devices,
        "device_count": len(devices),
    }


class Handler(BaseHTTPRequestHandler):
    """Handle hardware monitoring HTTP requests."""

    def do_GET(self):

        if self.path not in (
            "/health",
            "/telemetry",
            "/remediation",
        ):
            self.send_error(404, "Endpoint not found")
            return

        if self.path == "/health":
            result = {
                "status": "ok",
                "service": "simulated-hardware-health",
            }

        else:
            if not DATA.exists():
                self.send_error(
                    503,
                    "Telemetry file missing; run collector first",
                )
                return

            try:
                lines = DATA.read_text(
                    encoding="utf-8"
                ).splitlines()

                if self.path == "/telemetry":
                    result = analyze(lines)

                elif self.path == "/remediation":
                    result = simulate_remediation(lines)

            except (OSError, ValueError, KeyError, TypeError) as error:
                self.send_error(
                    500,
                    f"Telemetry processing error: {error}",
                )
                return

        # Convert result to JSON
        response = json.dumps(result).encode("utf-8")

        # Return HTTP 200 response
        self.send_response(200)

        self.send_header(
            "Content-Type",
            "application/json",
        )

        self.send_header(
            "Content-Length",
            str(len(response)),
        )

        self.end_headers()

        self.wfile.write(response)


if __name__ == "__main__":

    PORT = int(os.environ.get("PORT", 8080))

    server = ThreadingHTTPServer(
        ("127.0.0.1", PORT),
        Handler,
    )

    print(
        f"Serving http://127.0.0.1:{PORT}",
        flush=True,
    )

    try:
        server.serve_forever()

    except KeyboardInterrupt:
        print("\nStopping hardware monitoring API...")

    finally:
        server.server_close()
        print("Server stopped.")
